// Byte offset of each runtime entry point / data slot within the blob.
struct Label { const char* name; uint32_t off; };
inline constexpr Label LABELS[] = {
    { "_start", 0xaf7 },
    { "wandaa_append_file", 0x461 },
    { "wandaa_array_new", 0x8b4 },
    { "wandaa_crash_handler", 0x2b1 },
    { "wandaa_current_line", 0x10 },
    { "wandaa_empty_str", 0x40 },
    { "wandaa_init_stdout", 0x260 },
    { "wandaa_int_to_str", 0x7a6 },
    { "wandaa_print_float", 0x917 },
    { "wandaa_print_int", 0x2f3 },
    { "wandaa_print_str", 0x280 },
    { "wandaa_print_strval", 0x372 },
    { "wandaa_read_file", 0x4f4 },
    { "wandaa_str_at", 0x6f6 },
    { "wandaa_str_concat", 0x3ac },
    { "wandaa_str_eq", 0x437 },
    { "wandaa_str_from_c", 0x672 },
    { "wandaa_str_len", 0x36d },
    { "wandaa_str_to_int", 0x860 },
    { "wandaa_substr", 0x70d },
    { "wandaa_write_file", 0x5df },
};
inline constexpr size_t LABEL_COUNT = sizeof(LABELS)/sizeof(LABELS[0]);

inline uint32_t labelOffset(const std::string& name) {
    for (size_t i = 0; i < LABEL_COUNT; ++i)
        if (name == LABELS[i].name) return LABELS[i].off;
    throw std::runtime_error("runtime blob has no label: " + name);
}
inline bool hasLabel(const std::string& name) {
    for (size_t i = 0; i < LABEL_COUNT; ++i)
        if (name == LABELS[i].name) return true;
    return false;
}

